package com.fitlife.comunidade.controller;
import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/comunidade/eventos") public class EventoController{private final JdbcTemplate jdbc;public EventoController(JdbcTemplate j){jdbc=j;}
 private List<Map<String,Object>> query(String sql,Object...args){return jdbc.query(sql,(rs,n)->{Map<String,Object>m=new LinkedHashMap<>();m.put("id",rs.getString("id"));m.put("nome",rs.getString("nome"));m.put("data",rs.getString("data_evento"));m.put("local",rs.getString("local"));m.put("descricao",rs.getString("descricao"));m.put("imagem",rs.getString("imagem"));m.put("criado",rs.getObject("criado_por")!=null);m.put("criadoPor",rs.getObject("criado_por"));if(hasColumn(rs,"inscrito"))m.put("inscrito",rs.getBoolean("inscrito"));return m;},args);}
 private boolean hasColumn(java.sql.ResultSet rs,String name){try{rs.findColumn(name);return true;}catch(Exception e){return false;}}
 @GetMapping public List<Map<String,Object>> listar(@RequestParam(required=false)Long usuarioId){if(usuarioId==null)return query("SELECT e.*,0 AS inscrito FROM evento e ORDER BY e.data_evento");return query("SELECT e.*,CASE WHEN p.usuario_id IS NULL THEN 0 ELSE 1 END AS inscrito FROM evento e LEFT JOIN evento_participante p ON p.evento_id=e.id AND p.usuario_id=? ORDER BY e.data_evento",usuarioId);}
 @GetMapping("/usuario/{usuarioId}")public List<Map<String,Object>> meus(@PathVariable long usuarioId){return query("SELECT e.*,1 AS inscrito FROM evento e JOIN evento_participante p ON p.evento_id=e.id WHERE p.usuario_id=? ORDER BY e.data_evento",usuarioId);}
 @PostMapping @Transactional @ResponseStatus(HttpStatus.CREATED)public Map<String,Object> criar(@RequestBody Map<String,Object>d){validar(d);String id=UUID.randomUUID().toString();jdbc.update("INSERT INTO evento(id,nome,data_evento,local,descricao,imagem,criado_por) VALUES(?,?,?,?,?,?,?)",id,d.get("nome"),d.get("data"),d.get("local"),d.get("descricao"),d.get("imagem"),Long.valueOf(d.get("usuarioId").toString()));jdbc.update("INSERT INTO evento_participante(evento_id,usuario_id) VALUES(?,?)",id,Long.valueOf(d.get("usuarioId").toString()));return buscar(id);}
 @PutMapping("/{id}")public Map<String,Object> atualizar(@PathVariable String id,@RequestBody Map<String,Object>d){validar(d);Long dono=jdbc.query("SELECT criado_por FROM evento WHERE id=?",rs->rs.next()?(Long)rs.getObject(1):null,id);if(dono==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Evento não encontrado.");if(!dono.toString().equals(String.valueOf(d.get("usuarioId"))))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Somente quem criou pode editar este evento.");jdbc.update("UPDATE evento SET nome=?,data_evento=?,local=?,descricao=?,imagem=? WHERE id=?",d.get("nome"),d.get("data"),d.get("local"),d.get("descricao"),d.get("imagem"),id);return buscar(id);}
 @PostMapping("/{id}/participacoes")public Map<String,Object> participar(@PathVariable String id,@RequestBody Map<String,Object>d){Long uid=Long.valueOf(d.get("usuarioId").toString());if(buscarOuNull(id)==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Evento não encontrado.");jdbc.update("INSERT IGNORE INTO evento_participante(evento_id,usuario_id) VALUES(?,?)",id,uid);return Map.of("participando",true,"eventoId",id);}
 private Map<String,Object>buscar(String id){Map<String,Object>e=buscarOuNull(id);if(e==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Evento não encontrado.");return e;}
 private Map<String,Object>buscarOuNull(String id){List<Map<String,Object>>r=query("SELECT e.*,0 AS inscrito FROM evento e WHERE e.id=?",id);return r.isEmpty()?null:r.get(0);}
 private void validar(Map<String,Object>d){for(String k:List.of("nome","data","local"))if(d.get(k)==null||d.get(k).toString().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Informe nome, data e local do evento.");if(d.get("usuarioId")==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Usuário não identificado.");}
}
